var n=`0650-domoda`;var i=`world-0650`;var a=`GM`;var o=`western-africa`;var s=4;var r=75;var g={en:`Domoda`,ua:`Домода`};var h={en:`Domoda is a Gambia classic prepared with chicken thigh, yellow onion, tomato, scotch bonnet pepper. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Домода, страва кухні країни Гамбія зі складниками: куряче стегно, жовта цибуля, помідор, перець скотч-боннет. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var d=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 11 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 11 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:11,i:[[`chicken-thigh`,720,`g`],[`yellow-onion`,180,`g`],[`sunflower-oil`,45,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`tomato`,240,`g`],[`scotch-bonnet-pepper`,1,`pcs`],[`garlic`,3,`clove`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 50 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 50 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:50,i:[[`peanut-butter`,190,`g`],[`water`,820,`ml`],[`sweet-potato`,290,`g`],[`carrot`,210,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`parsley`,18,`g`]]}];var l={slug:n,id:i,country:`GM`,region:o,servings:4,minutes:75,title:g,text:h,steps:d};export{a as country,l as default,i as id,r as minutes,o as region,s as servings,n as slug,d as steps,h as text,g as title};